/*!
 * pdf-lib.min.js — a tiny, self-contained image-to-PDF writer.
 *
 * This is NOT the third-party jsPDF library. It's a small custom module
 * that writes a valid PDF file by hand (header, image XObjects, page
 * content streams, xref table, trailer). Each image is re-encoded as a
 * JPEG on a <canvas> and embedded with a DCTDecode filter, which keeps
 * the implementation tiny and dependency-free — important for an app
 * that has to work fully offline with nothing fetched from a CDN.
 *
 * Exposed API:
 *   PDFLib.createPdfFromImages(images, options) -> Promise<Blob>
 *     images:  array of { img: HTMLImageElement, width, height }
 *     options: {
 *       pageSize: 'fit' | 'a4' | 'letter' | 'legal',
 *       orientation: 'auto' | 'portrait' | 'landscape',
 *       margin: number (PDF points),
 *       quality: number (0–1, JPEG quality),
 *       onProgress: (fraction, label) => void
 *     }
 */
const PDFLib = (() => {

  const PAGE_SIZES = {
    // Sizes in PDF points (1 pt = 1/72 inch), portrait orientation.
    a4: [595.28, 841.89],
    letter: [612, 792],
    legal: [612, 1008]
  };

  function encoder() {
    return new TextEncoder();
  }

  // Renders an HTMLImageElement onto a canvas and returns raw JPEG bytes.
  function imageToJpegBytes(img, quality) {
    return new Promise((resolve, reject) => {
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth || img.width;
      canvas.height = img.naturalHeight || img.height;
      const ctx = canvas.getContext('2d');
      // White background so transparent PNGs don't turn black in JPEG.
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, 0, 0);
      canvas.toBlob(async (blob) => {
        if (!blob) { reject(new Error('Image encoding failed.')); return; }
        const buf = await blob.arrayBuffer();
        resolve({ bytes: new Uint8Array(buf), width: canvas.width, height: canvas.height });
      }, 'image/jpeg', quality);
    });
  }

  function pageDimsFor(pageSize, orientation, imgW, imgH, margin) {
    if (pageSize === 'fit') {
      return [imgW + margin * 2, imgH + margin * 2];
    }
    let [w, h] = PAGE_SIZES[pageSize] || PAGE_SIZES.a4;
    let wantLandscape;
    if (orientation === 'landscape') wantLandscape = true;
    else if (orientation === 'portrait') wantLandscape = false;
    else wantLandscape = imgW > imgH; // auto: match the image's own shape

    if (wantLandscape && h > w) [w, h] = [h, w];
    if (!wantLandscape && w > h) [w, h] = [h, w];
    return [w, h];
  }

  // Builds the PDF byte stream from prepared { jpegBytes, w, h } entries.
  function assemblePdf(pages) {
    const enc = encoder();
    const chunks = [];
    const offsets = [0]; // object 0 is reserved
    let pos = 0;

    function push(bytesOrString) {
      const bytes = typeof bytesOrString === 'string' ? enc.encode(bytesOrString) : bytesOrString;
      chunks.push(bytes);
      pos += bytes.length;
    }

    function startObj(n) {
      offsets[n] = pos;
      push(`${n} 0 obj\n`);
    }

    push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');

    const pageCount = pages.length;
    // Object numbering: 1 = Catalog, 2 = Pages, then for each page i (0-based):
    //   3 + i*3     = Page object
    //   3 + i*3 + 1 = Content stream
    //   3 + i*3 + 2 = Image XObject
    const catalogNum = 1;
    const pagesNum = 2;
    const firstDynamic = 3;

    startObj(catalogNum);
    push(`<< /Type /Catalog /Pages ${pagesNum} 0 R >>\nendobj\n`);

    const kids = [];
    for (let i = 0; i < pageCount; i++) kids.push(`${firstDynamic + i * 3} 0 R`);

    startObj(pagesNum);
    push(`<< /Type /Pages /Count ${pageCount} /Kids [${kids.join(' ')}] >>\nendobj\n`);

    pages.forEach((p, i) => {
      const pageNum = firstDynamic + i * 3;
      const contentNum = pageNum + 1;
      const imageNum = pageNum + 2;
      const [pw, ph] = p.pageDims;

      // Center the image within the page, respecting the margin.
      const availW = pw - p.margin * 2;
      const availH = ph - p.margin * 2;
      const scale = Math.min(availW / p.w, availH / p.h, 1) || 1;
      const drawW = p.w * scale;
      const drawH = p.h * scale;
      const x = (pw - drawW) / 2;
      const y = (ph - drawH) / 2;

      startObj(pageNum);
      push(
        `<< /Type /Page /Parent ${pagesNum} 0 R /MediaBox [0 0 ${pw.toFixed(2)} ${ph.toFixed(2)}] ` +
        `/Resources << /XObject << /Im0 ${imageNum} 0 R >> /ProcSet [/PDF /ImageC] >> ` +
        `/Contents ${contentNum} 0 R >>\nendobj\n`
      );

      const content = `q\n${drawW.toFixed(2)} 0 0 ${drawH.toFixed(2)} ${x.toFixed(2)} ${y.toFixed(2)} cm\n/Im0 Do\nQ`;
      const contentBytes = enc.encode(content);
      startObj(contentNum);
      push(`<< /Length ${contentBytes.length} >>\nstream\n`);
      push(contentBytes);
      push('\nendstream\nendobj\n');

      startObj(imageNum);
      push(
        `<< /Type /XObject /Subtype /Image /Width ${p.w} /Height ${p.h} ` +
        `/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${p.jpegBytes.length} >>\nstream\n`
      );
      push(p.jpegBytes);
      push('\nendstream\nendobj\n');
    });

    const xrefStart = pos;
    const totalObjs = firstDynamic + pageCount * 3;
    push(`xref\n0 ${totalObjs}\n`);
    push('0000000000 65535 f \n');
    for (let n = 1; n < totalObjs; n++) {
      push(`${String(offsets[n]).padStart(10, '0')} 00000 n \n`);
    }
    push(`trailer\n<< /Size ${totalObjs} /Root ${catalogNum} 0 R >>\nstartxref\n${xrefStart}\n%%EOF`);

    return new Blob(chunks, { type: 'application/pdf' });
  }

  async function createPdfFromImages(images, options) {
    const {
      pageSize = 'a4',
      orientation = 'auto',
      margin = 18,
      quality = 0.92,
      onProgress = () => {}
    } = options || {};

    const pages = [];
    for (let i = 0; i < images.length; i++) {
      onProgress(i / images.length, `Encoding image ${i + 1} of ${images.length}…`);
      const { img } = images[i];
      const { bytes, width, height } = await imageToJpegBytes(img, quality);
      const pageDims = pageDimsFor(pageSize, orientation, width, height, margin);
      pages.push({ jpegBytes: bytes, w: width, h: height, pageDims, margin });
      // Yield to the UI thread between images so the progress bar can repaint.
      await new Promise((r) => setTimeout(r, 0));
    }

    onProgress(0.98, 'Assembling PDF…');
    const blob = assemblePdf(pages);
    onProgress(1, 'Done.');
    return blob;
  }

  return { createPdfFromImages };
})();
